import React, { useState, useEffect } from 'react';
import { goalsAPI } from '../utils/api';
import { Plus, Edit, Trash2, Target } from 'lucide-react';
import toast from 'react-hot-toast';

const Goals = () => {
  const [goals, setGoals] = useState([]);
  const [filteredGoals, setFilteredGoals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingGoal, setEditingGoal] = useState(null);
  const [filters, setFilters] = useState({
    type: '',
    status: '',
    sortBy: 'deadline'
  });
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    deadline: '',
    progress: 0,
    type: 'short-term'
  });

  useEffect(() => {
    fetchGoals();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [goals, filters]);

  const applyFilters = () => {
    let filtered = [...goals];

    if (filters.type) {
      filtered = filtered.filter(goal => goal.type === filters.type);
    }

    if (filters.status === 'completed') {
      filtered = filtered.filter(goal => goal.completed);
    } else if (filters.status === 'in-progress') {
      filtered = filtered.filter(goal => !goal.completed && goal.progress > 0);
    } else if (filters.status === 'not-started') {
      filtered = filtered.filter(goal => !goal.completed && goal.progress === 0);
    }

    filtered.sort((a, b) => {
      if (filters.sortBy === 'deadline') {
        return new Date(a.deadline) - new Date(b.deadline);
      } else if (filters.sortBy === 'progress') {
        return b.progress - a.progress;
      }
      return 0;
    });

    setFilteredGoals(filtered);
  };

  const fetchGoals = async () => {
    try {
      const response = await goalsAPI.getAll();
      setGoals(response.data);
    } catch (error) {
      // Demo mode - use local storage
      const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
      setGoals(savedGoals);
      console.log('Using demo mode - goals stored locally');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingGoal) {
        await goalsAPI.update(editingGoal._id, formData);
        toast.success('Goal updated successfully');
      } else {
        await goalsAPI.create(formData);
        toast.success('Goal created successfully');
      }
      setShowModal(false);
      setEditingGoal(null);
      setFormData({ title: '', description: '', deadline: '', progress: 0, type: 'short-term' });
      fetchGoals();
    } catch (error) {
      // Demo mode - save to local storage
      const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
      const newGoal = {
        _id: Date.now().toString(),
        ...formData,
        completed: false,
        createdAt: new Date().toISOString()
      };

      if (editingGoal) {
        const updatedGoals = savedGoals.map(goal => 
          goal._id === editingGoal._id ? { ...goal, ...formData } : goal
        );
        localStorage.setItem('goals', JSON.stringify(updatedGoals));
        toast.success('Goal updated successfully (Demo Mode)');
      } else {
        savedGoals.push(newGoal);
        localStorage.setItem('goals', JSON.stringify(savedGoals));
        toast.success('Goal created successfully (Demo Mode)');
      }

      setShowModal(false);
      setEditingGoal(null);
      setFormData({ title: '', description: '', deadline: '', progress: 0, type: 'short-term' });
      fetchGoals();
    }
  };

  const handleEdit = (goal) => {
    setEditingGoal(goal);
    setFormData({
      title: goal.title,
      description: goal.description,
      deadline: goal.deadline.split('T')[0],
      progress: goal.progress,
      type: goal.type || 'short-term'
    });
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this goal?')) {
      try {
        await goalsAPI.delete(id);
        toast.success('Goal deleted successfully');
        fetchGoals();
      } catch (error) {
        // Demo mode - delete from local storage
        const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
        const updatedGoals = savedGoals.filter(goal => goal._id !== id);
        localStorage.setItem('goals', JSON.stringify(updatedGoals));
        toast.success('Goal deleted successfully (Demo Mode)');
        fetchGoals();
      }
    }
  };

  const handleProgressUpdate = async (id, progress) => {
    try {
      const completed = progress >= 100;
      await goalsAPI.update(id, { progress, completed });
      toast.success('Progress updated');
      fetchGoals();
    } catch (error) {
      // Demo mode - update in local storage
      const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
      const updatedGoals = savedGoals.map(goal => 
        goal._id === id ? { ...goal, progress, completed: progress >= 100 } : goal
      );
      localStorage.setItem('goals', JSON.stringify(updatedGoals));
      toast.success('Progress updated (Demo Mode)');
      fetchGoals();
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      <div className="max-w-7xl mx-auto py-6 px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Goals</h1>
          <button
            onClick={() => setShowModal(true)}
            className="inline-flex items-center px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Goal
          </button>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow p-4 mb-6">
          <div className="flex flex-wrap gap-4 items-center">
            <div className="flex items-center space-x-2">
              <Target className="w-4 h-4 text-gray-500" />
              <span className="text-sm font-medium text-gray-700">Filters:</span>
            </div>

            <select
              value={filters.type}
              onChange={(e) => setFilters({ ...filters, type: e.target.value })}
              className="px-3 py-1 border border-gray-300 rounded-md text-sm bg-white text-gray-900"
            >
              <option value="">All Types</option>
              <option value="short-term">Short Term</option>
              <option value="long-term">Long Term</option>
            </select>

            <select
              value={filters.status}
              onChange={(e) => setFilters({ ...filters, status: e.target.value })}
              className="px-3 py-1 border border-gray-300 rounded-md text-sm bg-white text-gray-900"
            >
              <option value="">All Status</option>
              <option value="not-started">Not Started</option>
              <option value="in-progress">In Progress</option>
              <option value="completed">Completed</option>
            </select>

            <select
              value={filters.sortBy}
              onChange={(e) => setFilters({ ...filters, sortBy: e.target.value })}
              className="px-3 py-1 border border-gray-300 rounded-md text-sm bg-white text-gray-900"
            >
              <option value="deadline">Sort by Deadline</option>
              <option value="progress">Sort by Progress</option>
            </select>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredGoals.length > 0 ? (
            filteredGoals.map((goal) => (
              <div key={goal._id} className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center">
                    <Target className="w-6 h-6 text-primary-600 mr-2" />
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white">{goal.title}</h3>
                  </div>
                  <div className="flex items-center space-x-2">
                    <button
                      onClick={() => handleEdit(goal)}
                      className="p-1 text-gray-400 hover:text-primary-600 dark:hover:text-primary-400"
                    >
                      <Edit className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(goal._id)}
                      className="p-1 text-gray-400 hover:text-red-600"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                {goal.description && (
                  <p className="text-gray-600 dark:text-gray-400 mb-4">{goal.description}</p>
                )}

                <div className="mb-4">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Progress</span>
                    <span className="text-sm text-gray-600 dark:text-gray-400">{goal.progress}%</span>
                  </div>
                  <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                    <div
                      className="bg-primary-600 h-2 rounded-full transition-all duration-300"
                      style={{ width: `${goal.progress}%` }}
                    ></div>
                  </div>
                </div>

                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Update Progress
                  </label>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    value={goal.progress}
                    onChange={(e) => handleProgressUpdate(goal._id, parseInt(e.target.value))}
                    className="w-full"
                  />
                </div>

                <div className="flex justify-between items-center text-sm mb-2">
                  <span className="text-gray-500 dark:text-gray-400">
                    Deadline: {new Date(goal.deadline).toLocaleDateString()}
                  </span>
                  <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                    goal.type === 'long-term' ? 'bg-purple-100 text-purple-800' : 'bg-blue-100 text-blue-800'
                  }`}>
                    {goal.type === 'long-term' ? 'Long Term' : 'Short Term'}
                  </span>
                </div>
                <div className="text-center">
                  {goal.completed && (
                    <span className="px-3 py-1 bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200 rounded-full text-xs font-medium">
                      ✅ Completed
                    </span>
                  )}
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full text-center py-12">
              <Target className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-600 dark:text-gray-400">
                {goals.length === 0 ? 'No goals yet. Set your first goal!' : 'No goals match your filters.'}
              </p>
            </div>
          )}
        </div>

        {/* Modal */}
        {showModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white dark:bg-gray-800 rounded-lg max-w-md w-full p-6">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
                {editingGoal ? 'Edit Goal' : 'Add New Goal'}
              </h2>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Title
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Description
                  </label>
                  <textarea
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    rows="3"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Goal Type
                  </label>
                  <select
                    value={formData.type}
                    onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  >
                    <option value="short-term">Short Term Goal</option>
                    <option value="long-term">Long Term Goal</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Deadline
                  </label>
                  <input
                    type="date"
                    required
                    value={formData.deadline}
                    onChange={(e) => setFormData({ ...formData, deadline: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>
                <div className="flex justify-end space-x-3 pt-4">
                  <button
                    type="button"
                    onClick={() => {
                      setShowModal(false);
                      setEditingGoal(null);
                      setFormData({ title: '', description: '', deadline: '', progress: 0, type: 'short-term' });
                    }}
                    className="px-4 py-2 text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-4 py-2 bg-primary-600 text-white rounded-md hover:bg-primary-700"
                  >
                    {editingGoal ? 'Update' : 'Create'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Goals;
